import numpy as np

def kosten(x):
    return (x - 3)**2 + 1

def ableitung_kosten(x, dx=1e-5):
    return (kosten(x + dx) - kosten(x - dx)) / (2 * dx)

x_aktuell = 0.0
alpha = 0.1

for i in range(5):
    grad = ableitung_kosten(x_aktuell)
    x_aktuell = x_aktuell - alpha * grad
    print(f"Iteration {i+1}: x = {x_aktuell:.4f},  K = {kosten(x_aktuell):.4f}")

